import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const EVIDENCE_TYPES = ['카드', '통장', '현금영수증', '전자세금계산서'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function intOf(value: unknown, fallback: number): number {
  const raw = text(value);
  if (raw === '') {
    return fallback;
  }
  if (!/^\d+$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 0 이상의 숫자여야 합니다.');
  }
  return Number(raw);
}

@Controller('api/v1')
export class FnSfr03209Controller {
  @Get('/evidences')
  async listEvidences(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const evidenceType = text(query['evidenceType']);
    const issueDateFrom = text(query['issueDateFrom']);
    const issueDateTo = text(query['issueDateTo']);
    const page = intOf(query['page'], 0);
    const size = intOf(query['size'], DEFAULT_SIZE);
    if (size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '크기는 1에서 200 사이여야 합니다.');
    }
    if (evidenceType !== '' && !EVIDENCE_TYPES.includes(evidenceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증빙 유형이 올바르지 않습니다.');
    }
    if (issueDateFrom !== '' && !DATE_PATTERN.test(issueDateFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작 일자는 YYYY-MM-DD 형식이어야 합니다.');
    }
    if (issueDateTo !== '' && !DATE_PATTERN.test(issueDateTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료 일자는 YYYY-MM-DD 형식이어야 합니다.');
    }
    return transaction(async (db) => {
      // 권한 범위: 조회 권한이 부여된 카드의 내역만 (AC-04)
      const where: string[] = [
        'EXISTS (SELECT 1 FROM credit_card_viewer v WHERE v.credit_card_id = ct.credit_card_id AND v.employee_id = CAST(:userId AS bigint))',
      ];
      const params: Record<string, unknown> = { userId: user.id };
      if (evidenceType !== '') {
        where.push('ct.evidence_type = :evidenceType');
        params['evidenceType'] = evidenceType;
      }
      if (issueDateFrom !== '') {
        where.push('ct.approved_at >= CAST(:issueDateFrom AS date)');
        params['issueDateFrom'] = issueDateFrom;
      }
      if (issueDateTo !== '') {
        where.push("ct.approved_at < CAST(:issueDateTo AS date) + interval '1 day'");
        params['issueDateTo'] = issueDateTo;
      }
      const whereSql = where.join(' AND ');
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM card_transaction ct WHERE ' + whereSql,
        params,
      );
      const total = Number(countRows[0]['total']);
      // 가정: 결의 사용 여부는 expense_resolution_id가 null이 아니면 true
      const items = await db.query(
        'SELECT ct.card_transaction_id AS "cardTransactionId", '
          + 'ct.approval_no AS "approvalNo", '
          + 'ct.total_amount AS "totalAmount", '
          + 'ct.evidence_type AS "evidenceType", '
          + 'ct.expense_resolution_id AS "expenseResolutionId", '
          + '(ct.expense_resolution_id IS NOT NULL) AS "usedInResolution" '
          + 'FROM card_transaction ct WHERE ' + whereSql
          + ' ORDER BY ct.approved_at DESC, ct.card_transaction_id DESC '
          + 'LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      return {
        items: items.map((row: Record<string, unknown>) => ({
          ...row,
          cardTransactionId: Number(row['cardTransactionId']),
          totalAmount: Number(row['totalAmount']),
          expenseResolutionId:
            row['expenseResolutionId'] === null ? null : Number(row['expenseResolutionId']),
        })),
        page,
        size,
        total,
      };
    });
  }
}

