import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer,
  Pairs, Tiles, Field, Select, DateInput, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const EVIDENCE_TYPES: [string, string][] = [
  ['카드', '카드'],
  ['통장', '통장'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

const PAGE_SIZE = 20;

export default function FnSfr03209Page({ role, notify }: PageProps) {
  const [evidenceType, setEvidenceType] = useState('');
  const [issueDateFrom, setIssueDateFrom] = useState('');
  const [issueDateTo, setIssueDateTo] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);

  const evidences = useData<Page>(
    () => call<Page>('GET', '/evidences', role, undefined, { ...applied, page, size: PAGE_SIZE }),
    [applied, page, role],
  );
  const resolutions = useData<Page>(
    () => call<Page>('GET', '/expense-resolutions', role, undefined, { page: 0, size: 5 }),
    [role],
  );

  const search = () => {
    if (issueDateFrom !== '' && issueDateTo !== '' && issueDateFrom > issueDateTo) {
      notify('조회 시작 일자가 종료 일자보다 늦습니다.');
      return;
    }
    setPage(0);
    setApplied({ evidenceType, issueDateFrom, issueDateTo });
  };

  const reset = () => {
    setEvidenceType('');
    setIssueDateFrom('');
    setIssueDateTo('');
    setPage(0);
    setApplied({});
  };

  const items = evidences.data ? evidences.data.items : [];
  const total = evidences.data ? evidences.data.total : 0;
  const usedCount = items.filter((row) => row['usedInResolution'] === true).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>증빙 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['이 쪽 결의 사용', <Num value={usedCount} />],
            ['이 쪽 결의 미사용', <Num value={items.length - usedCount} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>증빙자료</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="증빙 유형">
            <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_TYPES} placeholder="전체" />
          </Field>
          <Field label="조회 시작 일자">
            <DateInput value={issueDateFrom} onChange={setIssueDateFrom} />
          </Field>
          <Field label="조회 종료 일자">
            <DateInput value={issueDateTo} onChange={setIssueDateTo} />
          </Field>
        </Filters>
        <Band total={total} />
        {evidences.error !== '' && <ErrorText text={evidences.error} />}
        <DataTable
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            { key: 'totalAmount', label: '합계금액', render: (row) => <Num value={row['totalAmount']} /> },
            { key: 'evidenceType', label: '증빙 유형', render: (row) => <Badge value={row['evidenceType']} /> },
            {
              key: 'expenseResolutionId',
              label: '결의서',
              render: (row) => row['expenseResolutionId'] === null || row['expenseResolutionId'] === undefined
                ? <span>-</span>
                : <RefName table="expense_resolution" role={role} value={row['expenseResolutionId']} />,
            },
            { key: 'usedInResolution', label: '결의 사용 여부', render: (row) => <span>{row['usedInResolution'] === true ? '사용' : '미사용'}</span> },
          ]}
          rows={items}
          onRowClick={(row) => setDetail(row)}
          empty="조회 결과가 없습니다."
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>최근 지출결의</h2>
        {resolutions.error !== '' && <ErrorText text={resolutions.error} />}
        <DataTable
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'resolutionDate', label: '결의일자', render: (row) => <DateText value={row['resolutionDate']} /> },
            { key: 'amount', label: '결의 금액', render: (row) => <Num value={row['amount']} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (row) => <Badge value={row['approvalStatus']} /> },
          ]}
          rows={resolutions.data ? resolutions.data.items : []}
          empty="조회 결과가 없습니다."
        />
      </section>

      {detail !== null && (
        <Drawer title="증빙자료 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['승인번호', String(detail['approvalNo'] ?? '')],
              ['합계금액', <Num value={detail['totalAmount']} />],
              ['증빙 유형', <Badge value={detail['evidenceType']} />],
              [
                '결의서',
                detail['expenseResolutionId'] === null || detail['expenseResolutionId'] === undefined
                  ? '-'
                  : <RefName table="expense_resolution" role={role} value={detail['expenseResolutionId']} />,
              ],
              ['결의 사용 여부', detail['usedInResolution'] === true ? '사용' : '미사용'],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
